// Normaliza el payload de WhatsApp Cloud API
// El payload original está disponible en 'data' (que incluye body, headers, query...)

const raw = data || {};
const body = raw.body || {};
const query = raw.query || {};
const headers = raw.headers || {};

let event = { provider: 'whatsapp', type: 'unknown', message: null, contact: null, statuses: null, raw: body };

try {
  const entry = Array.isArray(body.entry) ? body.entry[0] : null;
  const change = entry && Array.isArray(entry.changes) ? entry.changes[0] : null;
  const value = change ? change.value || {} : {};

  // Mensajes entrantes
  if (Array.isArray(value.messages) && value.messages.length > 0) {
    const msg = value.messages[0];
    event.type = 'message';
    event.message = {
      id: msg.id,
      from: msg.from,
      timestamp: msg.timestamp,
      type: msg.type,
      text: msg.text?.body,
      image: msg.image,
      document: msg.document,
      audio: msg.audio,
      video: msg.video,
      interactive: msg.interactive,
      button: msg.button
    };
    if (Array.isArray(value.contacts) && value.contacts.length > 0) {
      event.contact = value.contacts[0];
    }
  }

  // Estados de mensajes (entregados, leídos, etc.)
  if (Array.isArray(value.statuses) && value.statuses.length > 0) {
    event.type = event.type === 'unknown' ? 'status' : event.type;
    event.statuses = value.statuses;
  }
} catch (e) {
  // Si algo falla, devolvemos el raw
}

return { query, headers, event };
